const crypto = require('crypto');
const src = $prevNode.name;
const b = $json.body || $json;
const out = (route, extra={}) => [{json:{...$json, route, ...extra}}];
const final = (body, code=200) => out('FINAL',{final:true,response_body:body,response_code:code,response_required:true});
const fail = (reason, code=400, extra={}) => final({ok:false,error_code:reason,...extra},code);
const normEmail = v => String(v||'').trim().toLowerCase();
const emailOk = e => /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]+([.][A-Za-z0-9-]+)+$/.test(String(e||'').trim()) && String(e||'').length<=254;
const inj = /(ignore (all|previous|prior) instructions|system prompt|developer message|api[_ -]?key|secret|token|forward (this|the message)|act as (system|developer)|override (the|all) (safety|policy|gate)|disable (suppression|safety)|bypass (approval|permission|gate))/i;
const scrub = v => {
  const s=String(v??'');
  return {text:s.replace(inj,/ /g), suspicious:inj.test(s)};
};
if (b && b.transition_request) {
  const t=b.transition_request;
  const leadId=String(t.lead_id||'');
  const requestedNext=String(t.new_status||'');
  if(!leadId || !requestedNext) return fail('TRANSITION_REQUEST_INVALID',400);

  // This is the single authoritative lifecycle graph. Dynamic event-terminal replay
  // is resolved against the locked current row, never by callers writing status directly.
  const edges=`VALUES
    ('DISCOVERED','VERIFIED'),('DISCOVERED','HOLD'),('DISCOVERED','REJECTED'),('DISCOVERED','SUPPRESSED'),('DISCOVERED','FAILED'),
    ('VERIFIED','RESEARCHED'),('VERIFIED','HOLD'),('VERIFIED','REJECTED'),('VERIFIED','SUPPRESSED'),('VERIFIED','FAILED'),
    ('RESEARCHED','DRAFTED'),('RESEARCHED','HOLD'),('RESEARCHED','REJECTED'),('RESEARCHED','SUPPRESSED'),('RESEARCHED','FAILED'),
    ('DRAFTED','DRAFTED'),('DRAFTED','QA'),('DRAFTED','HOLD'),('DRAFTED','REJECTED'),('DRAFTED','SUPPRESSED'),('DRAFTED','FAILED'),
    ('QA','APPROVED'),('QA','REVIEW'),('QA','DRAFTED'),('QA','HOLD'),('QA','REJECTED'),('QA','SUPPRESSED'),('QA','FAILED'),
    ('REVIEW','APPROVED'),('REVIEW','DRAFTED'),('REVIEW','HOLD'),('REVIEW','REJECTED'),('REVIEW','SUPPRESSED'),
    ('APPROVED','QUEUED'),('APPROVED','HOLD'),('APPROVED','REJECTED'),('APPROVED','SUPPRESSED'),
    ('QUEUED','SENT'),('QUEUED','HOLD'),('QUEUED','FAILED'),('QUEUED','SUPPRESSED'),
    ('SENT','BOUNCED'),('SENT','REPLIED'),('SENT','UNSUBSCRIBED'),('SENT','SUPPRESSED'),
    ('REPLIED','UNSUBSCRIBED'),('REPLIED','SUPPRESSED'),
    ('HOLD','DISCOVERED'),('HOLD','REVIEW'),('HOLD','REJECTED'),('HOLD','SUPPRESSED'),
    ('FAILED','HOLD'),('FAILED','REJECTED'),('FAILED','SUPPRESSED')`;

  const params=Array.isArray(t.params)?t.params:[];
  const N=params.length;

  // SOURCE-FIDELITY PARAMETER NAMESPACE:
  // Embedded pre/guard/post SQL retains its original $1..$N namespace.
  // Controller-generated lifecycle parameters begin strictly at N+1.
  const pLead=N+1, pNext=N+2, pEvent=N+3, pSource=N+4, pMeta=N+5,
        pRoute=N+6, pResp=N+7, pCode=N+8, pBody=N+9, pExpect=N+10,
        pContext=N+11;

  const pre=String(t.pre_sql||'').trim().replace(/;\s*$/,'');
  const guard=String(t.guard_sql||'').trim().replace(/;\s*$/,'');
  const post=String(t.post_sql||'').trim().replace(/;\s*$/,'');

  const preMutates=/(?:\bINSERT\b|\bUPDATE\b|\bDELETE\b|\bMERGE\b)/i.test(pre);
  const guardMutates=/(?:\bINSERT\b|\bUPDATE\b|\bDELETE\b|\bMERGE\b)/i.test(guard);
  const preSoftFailOnNoApply=t.pre_soft_fail_on_no_apply===true;

  const curSql=`SELECT lead_id,current_status,campaign_id FROM leads WHERE lead_id=$${pLead} FOR UPDATE`;
  const preCte=pre ? `pre AS (${pre}),` : '';
  const guardCte=guard ? `guard AS (${guard}),` : '';
  const postCte=post ? `post AS (${post}),` : '';

  const terminalMode=`COALESCE($${pMeta}::jsonb->>'terminal_replay_mode','')`;
  const effectiveStatus=`CASE
    WHEN ${terminalMode}='hard_bounce'
      AND c.current_status IN ('BOUNCED','SUPPRESSED','UNSUBSCRIBED','REJECTED','REPLIED')
      THEN c.current_status
    WHEN ${terminalMode}='unsubscribe'
      AND c.current_status IN ('UNSUBSCRIBED','SUPPRESSED','BOUNCED','REJECTED')
      THEN c.current_status
    WHEN ${terminalMode}='unsubscribe'
      AND c.current_status IN ('SENT','REPLIED')
      THEN 'UNSUBSCRIBED'
    WHEN ${terminalMode}='suppression'
      AND c.current_status IN ('SUPPRESSED','BOUNCED','UNSUBSCRIBED','REJECTED')
      THEN c.current_status
    WHEN ${terminalMode}='positive_reply'
      AND c.current_status IN ('REPLIED','BOUNCED','UNSUBSCRIBED','SUPPRESSED','REJECTED')
      THEN c.current_status
    ELSE $${pNext}::text
  END`;

  const expectedExpr=t.expected_status
    ? `($${pExpect}::text IS NULL OR c.current_status=$${pExpect}::text)`
    : 'TRUE';

  // Only explicit soft-precondition transitions (stable webhook event de-dupe)
  // are allowed to treat "pre did not apply" as a successful no-op. Any other
  // mutation path aborts the whole PostgreSQL statement if the mutation did not
  // produce the required row, preserving atomicity.
  const preOkExpr=preSoftFailOnNoApply
    ? `COALESCE((SELECT __pre_ok FROM pre LIMIT 1),FALSE)`
    : 'TRUE';
  const guardExists=guard ? 'EXISTS(SELECT 1 FROM guard)' : 'TRUE';
  const softNoApplyIsSafe=preSoftFailOnNoApply && !!pre && !guardMutates;
  const mutationAbortExpr=[
    (preMutates && !softNoApplyIsSafe) ? 'NOT EXISTS(SELECT 1 FROM pre)' : 'FALSE',
    (guardMutates) ? 'NOT EXISTS(SELECT 1 FROM guard)' : 'FALSE',
    `(NOT EXISTS(SELECT 1 FROM upd)) AND (` +
      `${(preMutates && !softNoApplyIsSafe) ? 'EXISTS(SELECT 1 FROM pre)' : 'FALSE'} OR ` +
      `${guardMutates ? 'EXISTS(SELECT 1 FROM guard)' : 'FALSE'})`
  ].join(' OR ');
  const postAbortExpr=post ? '(EXISTS(SELECT 1 FROM upd) AND NOT EXISTS(SELECT 1 FROM post))' : 'FALSE';
  const atomicAbortExpr=`(${mutationAbortExpr}) OR (${postAbortExpr})`;

  const sql=`WITH ${preCte}
  edges(prev_status,new_status) AS (${edges}),
  ${guardCte}
  cur AS (${curSql}),
  chk0 AS (
    SELECT c.*, ${effectiveStatus} AS desired_status
    FROM cur c
  ),
  chk AS (
    SELECT chk0.*,
      (desired_status=chk0.current_status) AS idempotent,
      (desired_status=chk0.current_status OR EXISTS(
        SELECT 1 FROM edges e
        WHERE e.prev_status=chk0.current_status AND e.new_status=desired_status
      )) AS legal,
      ${expectedExpr} AS expected_ok
    FROM chk0
  ),
  upd AS (
    UPDATE leads l
    SET current_status=c.desired_status,last_updated=now()
    FROM chk c
    WHERE l.lead_id=c.lead_id
      AND c.legal
      AND c.expected_ok
      AND ${preOkExpr}
      AND ${guardExists}
      AND (c.idempotent OR l.current_status=c.current_status)
    RETURNING l.lead_id,l.current_status,c.current_status AS previous_status,c.campaign_id,c.idempotent
  ),
  ${postCte}
  aud AS (
    INSERT INTO audit_events(
      ts,event_type,lead_id,campaign_id,source_system,previous_state,new_state,metadata
    )
    SELECT now(),$${pEvent},u.lead_id,u.campaign_id,$${pSource},
           u.previous_status,u.current_status,$${pMeta}::jsonb
    FROM upd u
  )
  SELECT
    CASE
      WHEN ${atomicAbortExpr}
      THEN CAST(current_timestamp::text AS integer)
      ELSE 1
    END AS _atomic_guard,
    jsonb_build_object(
      'db_ok',TRUE,
      'db_action','state_transition',
      'transition_applied',EXISTS(SELECT 1 FROM upd),
      'idempotent_replay',COALESCE((SELECT idempotent FROM upd LIMIT 1),FALSE),
      'previous_status',(SELECT previous_status FROM upd LIMIT 1),
      'new_status',(SELECT current_status FROM upd LIMIT 1),
      'lead_id',$${pLead},
      'next_route',$${pRoute},
      'response_required',$${pResp}::boolean,
      'response_code',COALESCE($${pCode}::int,200),
      'response_body',$${pBody}::jsonb,
      'context',$${pContext}::jsonb,
      'guard_applied',${guardExists},
      'pre_applied',${pre ? 'TRUE' : 'FALSE'},
      'pre_ok',${preOkExpr},
      'post_applied',${post ? 'EXISTS(SELECT 1 FROM post)' : 'TRUE'},
      'error_code',CASE
        WHEN NOT EXISTS(SELECT 1 FROM cur) THEN 'UNKNOWN_LEAD_ID'
        WHEN EXISTS(SELECT 1 FROM chk WHERE NOT legal) THEN 'ILLEGAL_TRANSITION'
        WHEN EXISTS(SELECT 1 FROM chk WHERE legal AND NOT expected_ok) THEN 'EXPECTED_STATE_MISMATCH'
        WHEN ${pre ? `NOT (${preOkExpr})` : 'FALSE'} THEN 'PRECONDITION_NOT_APPLIED'
        WHEN ${guard ? 'NOT EXISTS(SELECT 1 FROM guard)' : 'FALSE'} THEN 'TRANSITION_GUARD_FAILED'
        WHEN NOT EXISTS(SELECT 1 FROM upd) THEN 'CAS_FAILED'
        WHEN ${post ? 'NOT EXISTS(SELECT 1 FROM post)' : 'FALSE'} THEN 'POSTCONDITION_NOT_APPLIED'
        ELSE NULL
      END
    ) AS result;`;

  const allParams=[
    ...params,
    leadId,
    requestedNext,
    String(t.event||'State Transition'),
    String(t.source||'controller'),
    JSON.stringify(t.meta||{}),
    String(t.next_route||''),
    !!t.response_required,
    Number(t.response_code||200),
    JSON.stringify(t.response_body||{}),
    t.expected_status||null,
    JSON.stringify(t.context||{})
  ];

  return out('DB',{sql,params:allParams,transition_request:t});
}

// Returned here after the central transition transaction. Continue multi-step
// lifecycle paths without creating additional workflow nodes.
if($json.db_action==='state_transition' && $json.transition_applied===true){
  const c=$json.context||{};
  if(c.flow==='QA_LIFECYCLE'){
    if(c.phase==='DRAFTED'){
      return out('STATE',{transition_request:{lead_id:c.lead_id||$json.lead_id,new_status:'QA',event:'QA Evaluated',meta:{decision:c.decision,claim_verification:c.claim_verification||null},source:'qa',expected_status:'DRAFTED',next_route:'STATE',response_required:false,context:{...c,phase:'QA'}}});
    }
    if(c.phase==='REGENERATED'){
      return out('CONTENT',{content_stage:'AUTONOMOUS_DRAFT_CONTEXT',lead_id:c.lead_id||$json.lead_id,autonomous_run_id:c.autonomous_run_id||null,target_parameters:c.target_parameters||null,discovery_run:c.discovery_run||null,candidates:c.candidates||null,candidate_index:c.candidate_index??null,regeneration:true,autonomous_context:{...c,regeneration:true}});
    }
    if(c.phase==='QA'){
      if(c.decision==='PASS'){
        const auto=!!c.autonomous_run_id;
        return out('STATE',{transition_request:{lead_id:c.lead_id||$json.lead_id,new_status:'APPROVED',event:'QA Approved Automatically',meta:{qa_result:'PASS',approval_status:'AUTO_APPROVED'},source:'qa',expected_status:'QA',post_sql:`UPDATE leads l SET approval_status='AUTO_APPROVED',last_updated=now() FROM upd u WHERE l.lead_id=u.lead_id RETURNING l.lead_id`,next_route:auto?'SEND':'FINAL',response_required:true,response_code:200,response_body:c.response_body||{lead_id:c.lead_id||$json.lead_id,decision:'PASS'},context:{...c,phase:'APPROVED',...(auto?{send_stage:'AUTONOMOUS_QUEUE'}:{})}}});
      }
      if(c.decision==='REVIEW'){
        return out('STATE',{transition_request:{lead_id:c.lead_id||$json.lead_id,new_status:'REVIEW',event:'QA Review Required',meta:{reasons:c.reasons||[]},source:'qa',expected_status:'QA',post_sql:`WITH r AS (INSERT INTO review_queue(review_id,lead_id,review_type,reason,status,created_at) SELECT gen_random_uuid(),upd.lead_id,'QA_UNCERTAIN','QA_UNCERTAIN','PENDING',now() FROM upd RETURNING review_id),u AS (UPDATE leads l SET approval_status='PENDING_REVIEW',last_updated=now() FROM upd u WHERE l.lead_id=u.lead_id RETURNING l.lead_id) SELECT 1 FROM r`,next_route:'FINAL',response_required:true,response_code:200,response_body:c.response_body||{lead_id:c.lead_id||$json.lead_id,decision:'REVIEW'},context:{...c,phase:'REVIEW'}}});
      }
      if(c.decision==='REMOVE_REGENERATE'){
        return out('STATE',{transition_request:{lead_id:c.lead_id||$json.lead_id,new_status:'DRAFTED',event:'Regeneration Required',meta:{reasons:c.reasons||[],regeneration:true},source:'qa',expected_status:'QA',next_route:'STATE',response_required:false,response_code:200,response_body:c.response_body||{lead_id:c.lead_id||$json.lead_id,decision:'REMOVE_REGENERATE'},context:{...c,phase:'REGENERATED'}}});
      }
      return out('STATE',{transition_request:{lead_id:c.lead_id||$json.lead_id,new_status:'HOLD',event:'QA Stopped',meta:{reasons:c.reasons||[]},source:'qa',expected_status:'QA',post_sql:`WITH r AS (INSERT INTO review_queue(review_id,lead_id,review_type,reason,status,created_at) SELECT gen_random_uuid(),upd.lead_id,'QA_STOP','QA_STOP','PENDING',now() FROM upd RETURNING review_id) SELECT 1 FROM r`,next_route:'FINAL',response_required:true,response_code:200,response_body:c.response_body||{lead_id:c.lead_id||$json.lead_id,decision:'STOP'},context:{...c,phase:'HOLD'}}});
    }
  }
  if(c.flow==='HUMAN_REVIEW' && c.phase==='TRANSITIONED') return out('EVENT',{db_action:'human_review_commit_pending',lead_id:c.lead_id||$json.lead_id,approved:c.approved,reviewer:c.reviewer,review_id:c.review_id,response_body:c.response_body});
  if(c.flow==='AUTONOMOUS_RESEARCHED'){
    return out('CONTENT',{content_stage:'AUTONOMOUS_DRAFT_CONTEXT',lead_id:c.lead_id||$json.lead_id,autonomous_run_id:c.autonomous_run_id,target_parameters:c.target_parameters,discovery_run:c.discovery_run,candidates:c.candidates,candidate_index:c.candidate_index,research_result:c.research_result||null,autonomous_context:{discovery_only:!!c.discovery_only,target_parameters:c.target_parameters,discovery_run:c.discovery_run,candidates:c.candidates,candidate_index:c.candidate_index}});
  }
  if(c.flow==='AUTONOMOUS_LEAD_VERIFIED'){
    if(c.discovery_only===true) return out('AUTO',{auto_stage:'NEXT_CANDIDATE',discovery_run:c.discovery_run,candidates:c.candidates,target_parameters:c.target_parameters,candidate_index:Number(c.candidate_index||0)+1});
    return out('RESEARCH',{provider_action:'research',lead_id:c.lead_id||$json.lead_id,autonomous_run_id:c.autonomous_run_id,company:c.candidate,research_policy:c.target_parameters?.research_requirements||null,research_objective:c.target_parameters?.personalization_requirements||null,discovery_run:c.discovery_run,candidates:c.candidates,target_parameters:c.target_parameters,candidate_index:c.candidate_index});
  }
}
if (src === 'Reset Circuit Breaker (Admin)') {
  const op=(b.operator||'unknown');
  const sql=`WITH breaker AS (
    INSERT INTO system_flags(flag_key,flag_value,updated_at,updated_by,reason) VALUES
    ('CIRCUIT_BREAKER','CLOSED',now(),'admin',$1),
    ('CONSECUTIVE_SEND_FAILURES','0',now(),'admin',$1)
    ON CONFLICT(flag_key) DO UPDATE SET flag_value=excluded.flag_value,updated_at=now(),updated_by='admin',reason=excluded.reason
    RETURNING flag_key
  ), aud AS (
    INSERT INTO audit_events(ts,event_type,source_system,metadata) VALUES(now(),'CIRCUIT_BREAKER_RESET','admin',jsonb_build_object('operator',$1,'global_send_permission_restored',false))
  ) SELECT jsonb_build_object('db_ok',true,'db_action','breaker_reset','next_route','FINAL','response_required',true,'response_code',200,
    'response_body',jsonb_build_object('circuit_breaker','CLOSED','consecutive_send_failures',0,'global_send_permission','NOT_RESTORED_MANUAL_ACTION_REQUIRED','operator',$1)) AS result;`;
  return out('DB',{sql,params:[op]});
}
if (src === 'Receive Verification Result') {
  const lead_id=b.lead_id, raw=String(b.status||'ERROR').toUpperCase();
  if(!lead_id) return fail('LEAD_ID_REQUIRED');
  const route={VALID:'VERIFIED',INVALID:'REJECTED',UNKNOWN:'HOLD',CATCH_ALL_RISK:'HOLD',CATCH_ALL:'HOLD',ERROR:'HOLD',TIMEOUT:'HOLD'};
  const next=route[raw]||'HOLD';
  const pre_sql=`WITH l AS (SELECT 1 FROM leads WHERE lead_id=$1),
  vr AS(
    INSERT INTO email_verifications(verification_id,lead_id,provider,status,signals,verified_at)
    SELECT gen_random_uuid(),$1,$3,$2,$4::jsonb,now() FROM l
    RETURNING lead_id
  ),
  u AS(
    UPDATE leads
    SET verification_status=$2,verification_provider=$3,verification_signals=$4::jsonb,
        verification_timestamp=now(),
        candidate_rejection_reason=CASE WHEN $5='REJECTED' THEN 'EMAIL_'||$2 ELSE candidate_rejection_reason END,
        candidate_hold_reason=CASE WHEN $5='HOLD' THEN 'EMAIL_'||$2 ELSE candidate_hold_reason END,
        last_updated=now()
    WHERE lead_id=$1 AND EXISTS(SELECT 1 FROM vr)
    RETURNING lead_id
  ),
  rq AS(
    INSERT INTO review_queue(review_id,lead_id,review_type,reason,status,created_at)
    SELECT gen_random_uuid(),$1,'VERIFICATION_RISK','verification outcome requires hold','PENDING',now()
    FROM u WHERE $5='HOLD'
  )
  SELECT 1 FROM u;`;
  const guard_sql=`SELECT 1 FROM leads WHERE lead_id=$1 FOR UPDATE;`;
  return out('STATE',{transition_request:{lead_id,new_status:next,event:'Verification Result',meta:{status:raw,provider:b.provider||'verifier',signals:b.signals||{}},source:'verification',pre_sql,guard_sql,next_route:'FINAL',response_required:true,response_code:200,response_body:{lead_id,status:raw,action:raw==='VALID'?'CONTINUE':raw==='INVALID'?'REJECT':'HOLD'},params:[lead_id,raw,b.provider||'verifier',JSON.stringify(b.signals||{}),next],context:{}}});
}
if (src === 'Receive Discovery Candidate' || src === 'Receive Lead (Discovery/Import)') {
  const e=normEmail(b.email), cand=scrub(b.company_name||b.company||''), contact=scrub(b.contact_name||b.contact||''), title=scrub(b.job_title||b.title||'');
  const suspicious=cand.suspicious||contact.suspicious||title.suspicious;
  if(suspicious){
    const sql=`WITH a AS (INSERT INTO audit_events(ts,event_type,campaign_id,source_system,metadata) VALUES(now(),'PROMPT_INJECTION_SUSPECTED',$1,'discovery',jsonb_build_object('email_norm',$2,'fields','company/contact/title'))) SELECT jsonb_build_object('db_ok',true,'db_action','lead_intake_rejected','next_route','FINAL','response_required',true,'response_code',400,'response_body',jsonb_build_object('status','REJECTED','reason','PROMPT_INJECTION_SUSPECTED','email',$2)) AS result;`;
    return out('DB',{sql,params:[b.campaign_id||null,e]});
  }
  if(!b.lead_id || !b.campaign_id || !emailOk(e)) return fail('CRITICAL_FIELD_INVALID',400,{campaign_id:b.campaign_id||null,lead_id:b.lead_id||null});
  const leadId=String(b.lead_id);
  const sql=`WITH lock AS MATERIALIZED (SELECT pg_advisory_xact_lock(hashtext('lead-intake:'||$2::text||'|'||$3::text)) AS locked), campaign AS (SELECT campaign_id,status FROM campaigns WHERE campaign_id=$2), suppression AS (SELECT EXISTS(SELECT 1 FROM suppression s WHERE s.email_norm=$3) AS suppressed), dup AS (SELECT EXISTS(SELECT 1 FROM leads l,lock WHERE l.lead_id=$1 OR (l.campaign_id=$2 AND l.email_norm=$3) OR (l.email_norm=$3 AND l.current_status IN('SENT','REPLIED','BOUNCED','UNSUBSCRIBED','DISCOVERED','VERIFIED','RESEARCHED','DRAFTED','QA','REVIEW','APPROVED','QUEUED','HOLD','FAILED'))) AS duplicate), ins AS (INSERT INTO leads(lead_id,campaign_id,email,email_norm,company_name,contact_name,job_title,domain,location,industry,source,discovery_source,discovery_query,contact_source,email_discovery_source,enrichment_provider,target_parameters,company_validation_status,domain_validation_status,verification_status,current_status,created_at,last_updated) SELECT $1,$2,$3,$3,NULLIF($4,''),NULLIF($5,''),NULLIF($6,''),NULLIF($7,''),NULLIF($8,''),NULLIF($9,''),NULLIF($10,''),NULLIF($11,''),NULLIF($12,''),NULLIF($13,''),NULLIF($14,''),NULLIF($15,''),NULLIF($16,'')::jsonb,NULLIF($17,''),NULLIF($18,''),'PENDING','DISCOVERED',now(),now() FROM campaign c, suppression s, dup d, lock WHERE c.status='ACTIVE' AND NOT s.suppressed AND NOT d.duplicate RETURNING lead_id), aud AS (INSERT INTO audit_events(ts,event_type,lead_id,campaign_id,source_system,metadata) SELECT now(),CASE WHEN EXISTS(SELECT 1 FROM ins) THEN 'Lead Discovered' ELSE CASE WHEN NOT EXISTS(SELECT 1 FROM campaign) THEN 'Lead Intake Rejected: Campaign Missing' WHEN EXISTS(SELECT 1 FROM campaign WHERE status<>'ACTIVE') THEN 'Lead Intake Rejected: Campaign Inactive' WHEN (SELECT suppressed FROM suppression) THEN 'Lead Intake Suppressed' ELSE 'Lead Duplicate Prevented' END END,$1,$2,'intake',jsonb_build_object('email_norm',$3,'company',NULLIF($4,''),'source',$8,'campaign_active',EXISTS(SELECT 1 FROM campaign WHERE status='ACTIVE'),'suppressed',(SELECT suppressed FROM suppression),'duplicate',(SELECT duplicate FROM dup))) SELECT jsonb_build_object('db_ok',true,'db_action','lead_intake','lead_id',$1,'duplicate',(SELECT duplicate FROM dup),'suppressed',(SELECT suppressed FROM suppression),'campaign_exists',EXISTS(SELECT 1 FROM campaign),'campaign_active',EXISTS(SELECT 1 FROM campaign WHERE status='ACTIVE'),'accepted',EXISTS(SELECT 1 FROM ins),'next_route','FINAL','response_required',true,'response_code',CASE WHEN EXISTS(SELECT 1 FROM ins) THEN 200 ELSE CASE WHEN NOT EXISTS(SELECT 1 FROM campaign) THEN 404 WHEN EXISTS(SELECT 1 FROM campaign WHERE status<>'ACTIVE') THEN 409 WHEN (SELECT suppressed FROM suppression) THEN 409 ELSE 409 END END,'response_body',jsonb_build_object('lead_id',$1,'accepted',EXISTS(SELECT 1 FROM ins),'duplicate',(SELECT duplicate FROM dup),'suppressed',(SELECT suppressed FROM suppression),'campaign_active',EXISTS(SELECT 1 FROM campaign WHERE status='ACTIVE'))) AS result;`;
  return out('DB',{sql,params:[leadId,b.campaign_id,e,cand.text,contact.text,title.text,String(b.domain||''),String(b.location||''),String(b.industry||''),String(b.source||src),String(b.discovery_source||''),String(b.discovery_query||''),String(b.contact_source||''),String(b.email_discovery_source||''),String(b.enrichment_provider||''),JSON.stringify(b.target_parameters||{}),String(b.company_validation_status||''),String(b.domain_validation_status||'')]});
}
return fail('UNSUPPORTED_STATE_ENTRY',{source:src});

const crypto = require('crypto');
const src = $prevNode.name;
const b = $json.body || $json;
const out = (route, extra={}) => [{json:{...$json,route,...extra}}];
const final = (body, code=200) => out('FINAL',{final:true,response_body:body,response_code:code,response_required:true});
const fail = (reason,code=400,extra={}) => final({ok:false,error_code:reason,...extra},code);
const scrub = v => {
  const s=String(v??'');
  const p=/(ignore (all|previous|prior) instructions|system prompt|developer message|api[_ -]?key|secret|token|forward (this|the message)|act as (system|developer)|override (the|all) (safety|policy|gate)|disable (suppression|safety)|bypass (approval|permission|gate))/i;
  return {text:s.replace(p,' '),suspicious:p.test(s)};
};
const placeholders = t => {
  const ps=[/\[[^\]]{1,40}\]/g,/\{\{[^}]*\}\}/g,/\$\{[^}]*\}/g,/<[A-Z][A-Z _]{1,30}>/g,/%[A-Z_]{2,30}%/g,/(?<![A-Za-z0-9_])(undefined|null|NaN)(?![A-Za-z0-9_])/g,/(?<![A-Za-z0-9_])N\/A(?![A-Za-z0-9_])/g,/\b(?:TBD|TODO|XXX+)\b/gi];
