  const currentQaDecision=L.latest_qa_decision||null;
  const autoApprovalOk=L.qa_result==='PASS' && L.approval_status==='AUTO_APPROVED' && currentQaDecision==='PASS';
  const humanApprovalOk=L.qa_result==='REVIEW' && L.approval_status==='HUMAN_APPROVED' && currentQaDecision==='REVIEW';
  if(!autoApprovalOk && !humanApprovalOk)errs.push('QA_APPROVAL_NOT_VALID');
  if(currentQaDraft!==L.latest_draft_id)errs.push('QA_DRAFT_BINDING_MISMATCH');
  if(L.qa_claim_verification_overall!=='PASS')errs.push('AUTOMATIC_CLAIM_VERIFICATION_NOT_PASSED');

  const draftClaims=Array.isArray(L.draft_claim_ids)?L.draft_claim_ids:[];
  const supported=Array.isArray(L.qa_supported_claim_ids)?L.qa_supported_claim_ids:[];
  if(draftClaims.some(id=>!supported.includes(id)))errs.push('UNSUPPORTED_CLAIM_ID');

  if(['SENT','REPLIED','BOUNCED','UNSUBSCRIBED'].includes(L.current_status)||L.dup_elsewhere)
    errs.push('DUPLICATE_OR_ALREADY_SENT');
  if(L.is_suppressed)errs.push('SUPPRESSED');

  if(mode==='QUEUE'){
    if(L.queue_state && !['QUEUED','CANCELLED'].includes(L.queue_state) && L.current_status==='APPROVED')
      errs.push('UNEXPECTED_EXISTING_QUEUE_STATE');
  }
  if(mode==='FINAL_SEND'){
    if(!['QUEUED','RETRY_WAIT'].includes(L.queue_state))errs.push('QUEUE_NOT_SENDABLE');
    if(!L.queue_id)errs.push('QUEUE_IDENTITY_UNKNOWN');
    if(L.queue_campaign_id && String(L.queue_campaign_id)!==String(L.campaign_id))errs.push('QUEUE_CAMPAIGN_BINDING_MISMATCH');
    if(L.provider_message_id)errs.push('PROVIDER_MESSAGE_ID_ALREADY_PRESENT');
    if(!Number.isInteger(Number(L.attempt_count))||Number(L.attempt_count)<0||Number(L.attempt_count)>=3)errs.push('ATTEMPT_LIMIT_INVALID');
    if(L.queue_state==='RETRY_WAIT'){const nt=new Date(L.next_attempt_at||'');if(!L.next_attempt_at||Number.isNaN(nt.getTime())||nt.getTime()>nowMs)errs.push('RETRY_NOT_DUE');}
    if(L.queue_state==='QUEUED'&&L.next_attempt_at){const nt=new Date(L.next_attempt_at);if(!Number.isNaN(nt.getTime())&&nt.getTime()>nowMs)errs.push('QUEUE_NOT_SENDABLE_YET');}
    if(Number(L.idempotency_conflict||0)>0)errs.push('IDEMPOTENCY_CONFLICT');
    if(!L.idempotency_key||!expectedIdk||L.idempotency_key!==expectedIdk)errs.push('IDEMPOTENCY_KEY_INVALID');
  }
  if(mode==='PROVIDER_SEND'){
    if(L.queue_state!=='SENDING')errs.push('QUEUE_NOT_SENDING');
    if(!L.queue_id||L.queue_id!==L.expected_queue_id)errs.push('QUEUE_IDENTITY_INVALID');
    if(L.queue_campaign_id && String(L.queue_campaign_id)!==String(L.campaign_id))errs.push('QUEUE_CAMPAIGN_BINDING_MISMATCH');
    if(L.queue_draft_id!==L.latest_draft_id)errs.push('QUEUE_DRAFT_BINDING_MISMATCH');
    if(!Number.isInteger(Number(L.attempt_count))||Number(L.attempt_count)<1||Number(L.attempt_count)>3)errs.push('ATTEMPT_COUNT_INVALID');
    if(L.provider_message_id)errs.push('PROVIDER_MESSAGE_ID_ALREADY_PRESENT');
    if(Number(L.idempotency_conflict||0)>0)errs.push('IDEMPOTENCY_CONFLICT');
    if(!L.idempotency_key||!expectedIdk||L.idempotency_key!==expectedIdk)errs.push('IDEMPOTENCY_KEY_INVALID');
    if(L.reservation_acquired!==true || Number(L.reserved_sent_count||0)<=0)errs.push('DAILY_RESERVATION_MISSING');
    if(L.lock_count!==1 || L.lock_holder!==L.holder)errs.push('SEND_LOCK_INVALID');
    if(Number(L.lock_seconds_remaining||0)<20)errs.push('SEND_LOCK_TOO_CLOSE_TO_EXPIRY');
    if(L.pending_ambiguous_review)errs.push('PENDING_AMBIGUOUS_SEND_REVIEW');
    if(Number(L.daily_after_reservation)<1)errs.push('DAILY_COUNTER_RESERVATION_INVALID');
  }

  const sent=Number(L.sent_today),lim=Number(L.daily_limit);
  if(mode!=='PROVIDER_SEND'){
    if(L.sent_today===null||L.sent_today===undefined||!Number.isInteger(sent)||sent<0||!Number.isInteger(lim)||lim<=0)
      errs.push('DAILY_LIMIT_STATE_INVALID');
    else if(sent>=lim)errs.push('DAILY_LIMIT');
  }else{
    if(!Number.isInteger(lim)||lim<=0)errs.push('DAILY_LIMIT_STATE_INVALID');
    if(L.sent_today===null||L.sent_today===undefined||!Number.isInteger(sent)||sent<0)errs.push('DAILY_COUNTER_STATE_INVALID');
    if(Number.isInteger(sent)&&Number.isInteger(lim)&&sent>lim)errs.push('DAILY_LIMIT_EXCEEDED_AFTER_RESERVATION');
  }

  if(!['AUTO_APPROVED','HUMAN_APPROVED'].includes(L.approval_status))errs.push('NOT_APPROVED');
  if(L.approval_status==='HUMAN_REJECTED')errs.push('HUMAN_REJECTED');
  if(flags.GLOBAL_SEND_PERMISSION!=='TRUE')errs.push('GLOBAL_SEND_PERMISSION_FALSE');
  if(flags.CIRCUIT_BREAKER!=='CLOSED')errs.push('CIRCUIT_BREAKER_OPEN');
  if(flags.SYSTEM_ANOMALY!=='FALSE')errs.push('SYSTEM_ANOMALY_BLOCKED');

  if(mode==='FINAL_SEND'){
    if(L.pending_ambiguous_review)errs.push('PENDING_AMBIGUOUS_SEND_REVIEW');
    if(L.active_lock_count!==undefined && Number(L.active_lock_count)!==1)errs.push('SEND_LOCK_MULTIPLICITY_INVALID');
    if(L.active_lock_holder && L.holder && L.active_lock_holder!==L.holder)errs.push('SEND_LOCK_HOLDER_MISMATCH');
    if(!L.holder_expiry||new Date(L.holder_expiry).getTime()<=nowMs)errs.push('SEND_LOCK_EXPIRED');
    if(L.autonomous_run_id){
      if(L.autonomous_run_missing)errs.push('AUTONOMOUS_RUN_UNKNOWN');
      else if(Number(L.autonomous_slot_count)>Number(L.autonomous_requested_send_count||0))errs.push('AUTONOMOUS_SEND_TARGET_EXCEEDED');
    }
  }
  if(mode==='PROVIDER_SEND' && L.autonomous_run_id){
    if(L.autonomous_run_missing)errs.push('AUTONOMOUS_RUN_UNKNOWN');
    else if(Number(L.autonomous_slot_count)>Number(L.autonomous_requested_send_count||0))errs.push('AUTONOMOUS_SEND_TARGET_EXCEEDED');
  }

  const need=['database','queue','email_provider','workflow_engine'];
  const healthyRows=Array.isArray(health)?health:[];
  if(healthyRows.length!==4)errs.push('DEPENDENCY_NOT_HEALTHY');
  for(const comp of need){
    const h=healthyRows.find(x=>x.component===comp);
    const t=h&&h.checked_at?new Date(h.checked_at):null;
    const age=t&&!Number.isNaN(t.getTime())?nowMs-t.getTime():NaN;
    const fresh=!!h&&!!t&&!Number.isNaN(t.getTime())&&age>=0&&age<15*60*1000;
    if(!h||h.status!=='HEALTHY'||!fresh)errs.push('DEPENDENCY_NOT_HEALTHY:'+comp);
  }
  if(mode==='PROVIDER_SEND' && !String($env.EMAIL_PROVIDER_SEND_URL||'').trim())errs.push('EMAIL_PROVIDER_NOT_CONFIGURED');

  return [...new Set(errs)];
};
