    latest_qa_decision:$json.latest_qa_decision||null,
    draft_claim_ids:D.claim_ids||[],
    qa_result:L.qa_result,
    qa_claim_verification_overall:$json.qa_claim_verification_overall,
    qa_supported_claim_ids:Array.isArray($json.qa_supported_claim_ids)?$json.qa_supported_claim_ids:[],
    idempotency_conflict:$json.idempotency_conflict,
    pending_ambiguous_review:$json.pending_ambiguous_review,
    active_lock_count:$json.active_lock_count,
    active_lock_holder:$json.active_lock_holder,
    holder:$json.holder,
    holder_expiry:$json.holder_expiry,
    autonomous_run_id:Q.autonomous_run_id,
    autonomous_run_missing:$json.autonomous_run_missing,
    autonomous_slot_count:Number($json.autonomous_slot_count||0),
    autonomous_requested_send_count:Number($json.autonomous_requested_send_count||0)
  };
  if(Q.provider_message_id) return out('DB',{
    sql:`DELETE FROM send_locks WHERE lead_id=$1 AND holder=$2;
      SELECT jsonb_build_object('db_ok',true,'db_action','send_gate_blocked','next_route','FINAL','response_required',true,'response_code',409,
        'response_body',jsonb_build_object('sent',false,'reason','PROVIDER_MESSAGE_ID_ALREADY_PRESENT','lead_id',$1)) AS result;`,
    params:[L.lead_id,$json.holder]
  });

  const errs=gate(gateInput,health,flags,new Date().toISOString(),'FINAL_SEND');
  if(errs.length){
    return out('DB',{
      sql:`DELETE FROM send_locks WHERE lead_id=$1 AND holder=$2;
        SELECT jsonb_build_object('db_ok',true,'db_action','send_gate_blocked','next_route','FINAL','response_required',true,'response_code',409,
          'response_body',jsonb_build_object('sent',false,'reason',$3,'all_reasons',$4::jsonb,'lead_id',$1)) AS result;`,
      params:[L.lead_id,$json.holder,errs[0],JSON.stringify(errs)]
    });
  }

  const sendSql=`WITH run_lock AS MATERIALIZED(
      SELECT CASE
        WHEN q.autonomous_run_id IS NOT NULL
         THEN pg_advisory_xact_lock(hashtext('autonomous-send-target:'||q.autonomous_run_id::text))
        ELSE NULL
      END AS locked
      FROM send_queue q WHERE q.queue_id=$3
    ),
    latest_qa AS (
      SELECT qr.draft_id,qr.decision,qr.checks
      FROM qa_results qr
      WHERE qr.lead_id=$2
      ORDER BY qr.created_at DESC
      LIMIT 1
    ),
    critical_health AS (
      SELECT component,status,checked_at
      FROM (
        SELECT DISTINCT ON(component) component,status,checked_at
        FROM health_checks
        WHERE component IN('database','queue','email_provider','workflow_engine')
        ORDER BY component,checked_at DESC NULLS LAST
      ) h
    ),
    latest AS (
      SELECT
        l.lead_id,l.current_status,l.email,l.email_norm,l.campaign_id,l.verification_status,l.qa_result,l.approval_status,
        c.status AS campaign_status,c.start_date,c.end_date,c.sender_account,c.sender_identity,c.daily_limit,
        d.draft_id,d.subject,d.body,d.to_email,d.created_at,COALESCE(d.claim_ids,'[]'::jsonb) AS draft_claim_ids,
        q.queue_id,q.state AS queue_state,q.draft_id AS queue_draft_id,q.idempotency_key,q.autonomous_run_id,q.provider_message_id,
        COALESCE((SELECT sent_count FROM daily_send_counters WHERE campaign_id=l.campaign_id AND send_date=(now() AT TIME ZONE 'UTC')::date),0) AS sent_today,
        EXISTS(SELECT 1 FROM leads x WHERE x.email_norm=l.email_norm AND x.lead_id<>l.lead_id AND x.current_status IN('SENT','REPLIED','BOUNCED','UNSUBSCRIBED')) AS dup_elsewhere,
        EXISTS(SELECT 1 FROM suppression s WHERE s.email_norm=l.email_norm) AS is_suppressed,
        COALESCE((SELECT flag_value FROM system_flags WHERE flag_key='GLOBAL_SEND_PERMISSION'),'UNKNOWN') AS global_perm,
        COALESCE((SELECT flag_value FROM system_flags WHERE flag_key='CIRCUIT_BREAKER'),'UNKNOWN') AS breaker,
        COALESCE((SELECT flag_value FROM system_flags WHERE flag_key='SYSTEM_ANOMALY'),'UNKNOWN') AS anomaly,
        COALESCE((SELECT checks->'claim_verification'->>'overall' FROM latest_qa),'UNKNOWN') AS qa_claim_verification_overall,
        COALESCE((SELECT checks->'supported_claim_ids' FROM latest_qa),'[]'::jsonb) AS qa_supported_claim_ids,
        COALESCE((SELECT draft_id FROM latest_qa),'') AS latest_qa_draft_id,
        COALESCE((SELECT decision FROM latest_qa),'') AS latest_qa_decision,
        EXISTS(SELECT 1 FROM review_queue r WHERE r.lead_id=l.lead_id AND r.review_type='AMBIGUOUS_SEND' AND r.status='PENDING') AS pending_ambiguous_review,
        (SELECT COUNT(*) FROM send_locks sl WHERE sl.lead_id=l.lead_id AND sl.expires_at>now()) AS lock_count,
        (SELECT sl.holder FROM send_locks sl WHERE sl.lead_id=l.lead_id AND sl.expires_at>now() ORDER BY sl.expires_at DESC LIMIT 1) AS lock_holder,
        (SELECT sl.expires_at FROM send_locks sl WHERE sl.lead_id=l.lead_id AND sl.expires_at>now() AND sl.holder=$4 ORDER BY sl.expires_at DESC LIMIT 1) AS holder_expiry,
        (SELECT COUNT(*) FROM critical_health h WHERE h.status='HEALTHY' AND h.checked_at IS NOT NULL AND h.checked_at<=now() AND h.checked_at>now()-interval '15 minutes') AS fresh_critical_health_count,
        CASE WHEN q.autonomous_run_id IS NULL THEN 0 ELSE (SELECT COUNT(*) FROM send_queue qs WHERE qs.autonomous_run_id=q.autonomous_run_id AND qs.state IN('QUEUED','SENDING','RETRY_WAIT','AMBIGUOUS','SENT')) END AS autonomous_slot_count,
        CASE WHEN q.autonomous_run_id IS NULL THEN 0 ELSE COALESCE((SELECT requested_send_count FROM autonomous_campaign_runs ar WHERE ar.discovery_run_id=q.autonomous_run_id),0) END AS autonomous_requested_send_count,
        CASE WHEN q.autonomous_run_id IS NULL THEN false ELSE NOT EXISTS(SELECT 1 FROM autonomous_campaign_runs ar WHERE ar.discovery_run_id=q.autonomous_run_id) END AS autonomous_run_missing
      FROM leads l
      JOIN campaigns c ON c.campaign_id=l.campaign_id
      JOIN send_queue q ON q.queue_id=$3 AND q.lead_id=l.lead_id
      LEFT JOIN LATERAL(SELECT * FROM email_drafts WHERE lead_id=l.lead_id ORDER BY created_at DESC LIMIT 1)d ON true
      CROSS JOIN run_lock
      WHERE l.lead_id=$2
    ),
    reserved AS (
      INSERT INTO daily_send_counters(campaign_id,send_date,sent_count)
      SELECT x.campaign_id,(now() AT TIME ZONE 'UTC')::date,1
      FROM latest x
      WHERE x.sent_today<x.daily_limit
        AND x.dup_elsewhere=false AND x.is_suppressed=false
        AND x.global_perm='TRUE' AND x.breaker='CLOSED' AND x.anomaly='FALSE'
        AND x.current_status='QUEUED' AND x.verification_status='VALID'
        AND ((x.qa_result='PASS' AND x.approval_status='AUTO_APPROVED' AND x.latest_qa_decision='PASS')
          OR (x.qa_result='REVIEW' AND x.approval_status='HUMAN_APPROVED' AND x.latest_qa_decision='REVIEW'))
        AND x.campaign_status='ACTIVE'
        AND (x.start_date IS NULL OR (now() AT TIME ZONE 'UTC')::date>=x.start_date)
        AND (x.end_date IS NULL OR (now() AT TIME ZONE 'UTC')::date<=x.end_date)
        AND x.queue_state IN('QUEUED','RETRY_WAIT') AND x.queue_id=$3
        AND x.queue_draft_id=x.draft_id AND x.draft_id IS NOT NULL
        AND lower(coalesce(x.to_email,''))=lower(coalesce(x.email_norm,''))
        AND x.latest_qa_draft_id=x.draft_id
        AND x.qa_claim_verification_overall='PASS'
        AND NOT EXISTS(
          SELECT 1
          FROM jsonb_array_elements_text(COALESCE(x.draft_claim_ids,'[]'::jsonb)) cid
          WHERE NOT (COALESCE(x.qa_supported_claim_ids,'[]'::jsonb) ? cid.value)
        )
        AND x.pending_ambiguous_review=false
        AND x.provider_message_id IS NULL
        AND x.idempotency_key=encode(digest(x.campaign_id::text||'|'||lower(x.email_norm),'sha256'),'hex')
        AND x.fresh_critical_health_count=4
        AND x.autonomous_run_missing=false
        AND x.autonomous_slot_count<=x.autonomous_requested_send_count
        AND EXISTS(SELECT 1 FROM send_locks sl WHERE sl.lead_id=$2 AND sl.holder=$4 AND sl.expires_at>now())
        AND (SELECT COUNT(*) FROM send_locks sl2 WHERE sl2.lead_id=$2 AND sl2.expires_at>now())=1
      ON CONFLICT (campaign_id,send_date) DO UPDATE
      SET sent_count=daily_send_counters.sent_count+1
      WHERE daily_send_counters.sent_count < (SELECT daily_limit FROM latest LIMIT 1)
      RETURNING campaign_id,sent_count
    ),
    mark AS (
      UPDATE send_queue q
      SET state='SENDING',attempt_count=COALESCE(q.attempt_count,0)+1,last_attempt_at=now(),next_attempt_at=NULL
      FROM latest x
      WHERE q.queue_id=$3 AND q.lead_id=$2 AND q.campaign_id=x.campaign_id
        AND q.state IN('QUEUED','RETRY_WAIT')
        AND q.draft_id=x.draft_id AND q.idempotency_key=x.idempotency_key
        AND EXISTS(SELECT 1 FROM reserved)
        AND EXISTS(SELECT 1 FROM send_locks sl WHERE sl.lead_id=q.lead_id AND sl.holder=$4 AND sl.expires_at>now())
        AND (SELECT COUNT(*) FROM send_locks sl2 WHERE sl2.lead_id=q.lead_id AND sl2.expires_at>now())=1
      RETURNING q.queue_id,q.attempt_count
    ),
    rollback AS (
      UPDATE daily_send_counters dc
      SET sent_count=GREATEST(0,dc.sent_count-1)
      WHERE dc.campaign_id=(SELECT campaign_id FROM latest)
        AND dc.send_date=(now() AT TIME ZONE 'UTC')::date
        AND EXISTS(SELECT 1 FROM reserved)
        AND NOT EXISTS(SELECT 1 FROM mark)
    )
    SELECT jsonb_build_object(
      'db_ok',true,'db_action','sending_prepared',
      'sending_cas_applied',EXISTS(SELECT 1 FROM mark),
      'reservation_acquired',EXISTS(SELECT 1 FROM reserved),
      'reserved_sent_count',COALESCE((SELECT sent_count FROM reserved LIMIT 1),0),
      'queue_id',$3,'lead_id',$2,'campaign_id',(SELECT campaign_id FROM latest),
      'attempt_count',COALESCE((SELECT attempt_count FROM mark LIMIT 1),0),
      'holder',$4,'draft_id',(SELECT draft_id FROM latest),
      'draft_subject',(SELECT subject FROM latest),'draft_body',(SELECT body FROM latest),
      'draft_to_email',(SELECT to_email FROM latest),'email_norm',(SELECT email_norm FROM latest),
      'sender_account',(SELECT sender_account FROM latest),'sender_identity',(SELECT sender_identity FROM latest),
      'idempotency_key',(SELECT idempotency_key FROM latest),
      'autonomous_run_id',(SELECT autonomous_run_id FROM latest),
      'next_route',CASE WHEN EXISTS(SELECT 1 FROM mark) THEN 'SEND' ELSE 'FINAL' END,
      'response_required',true,
      'response_code',CASE WHEN EXISTS(SELECT 1 FROM mark) THEN 200 ELSE 409 END,
      'response_body',CASE WHEN EXISTS(SELECT 1 FROM mark) THEN NULL ELSE jsonb_build_object('sent',false,'reason','FINAL_SEND_CAS_OR_DAILY_LIMIT_FAILED','lead_id',$2) END
    ) AS result;`;

  return out('DB',{
    sql:sendSql,
    params:[L.lead_id,L.lead_id,Q.queue_id,$json.holder],
    phase:'SENDING_PREPARED',
    email_send_context:{
      queue_id:Q.queue_id,lead_id:L.lead_id,campaign_id:C.campaign_id,holder:$json.holder,
      idempotency_key:Q.idempotency_key,email_norm:L.email_norm,draft_id:D.draft_id,
      draft_subject:D.subject,draft_body:D.body,draft_to_email:D.to_email,
      sender_account:C.sender_account,sender_identity:C.sender_identity,
      autonomous_run_id:Q.autonomous_run_id||$json.autonomous_run_id||null,
      target_parameters:$json.target_parameters||null,discovery_run:$json.discovery_run||null,
      candidates:$json.candidates||null,candidate_index:$json.candidate_index??null
    }
  });
}
if($json.db_action==='sending_prepared' && $json.sending_cas_applied===true){
  const ctxSend={
    queue_id:$json.queue_id,lead_id:$json.lead_id,campaign_id:$json.campaign_id,holder:$json.holder,
    idempotency_key:$json.idempotency_key,email_norm:$json.email_norm,draft_id:$json.draft_id,
    draft_subject:$json.draft_subject,draft_body:$json.draft_body,draft_to_email:$json.draft_to_email,
    sender_account:$json.sender_account,sender_identity:$json.sender_identity,
    autonomous_run_id:$json.autonomous_run_id||null,target_parameters:$json.target_parameters||null,
    discovery_run:$json.discovery_run||null,candidates:$json.candidates||null,
    candidate_index:$json.candidate_index??null,
    reservation_acquired:$json.reservation_acquired===true,
    reserved_sent_count:Number($json.reserved_sent_count||0),
    sending_attempt_count:Number($json.attempt_count||0)
  };
  const sql=`WITH latest_qa AS(
      SELECT qr.draft_id,qr.decision,qr.checks
      FROM qa_results qr WHERE qr.lead_id=$1
      ORDER BY qr.created_at DESC LIMIT 1
    ),
    critical_health AS(
      SELECT component,status,checked_at FROM(
        SELECT DISTINCT ON(component) component,status,checked_at
        FROM health_checks
        WHERE component IN('database','queue','email_provider','workflow_engine')
        ORDER BY component,checked_at DESC NULLS LAST
      ) h
    )
    SELECT jsonb_build_object(
      'db_ok',true,'db_action','final_provider_recheck',
      'lead',to_jsonb(l),'campaign',to_jsonb(c),'draft',to_jsonb(d),'queue',to_jsonb(q),
      'latest_qa_draft_id',(SELECT draft_id FROM latest_qa),
      'latest_qa_decision',(SELECT decision FROM latest_qa),
      'qa_claim_verification_overall',COALESCE((SELECT checks->'claim_verification'->>'overall' FROM latest_qa),'UNKNOWN'),
      'qa_supported_claim_ids',COALESCE((SELECT checks->'supported_claim_ids' FROM latest_qa),'[]'::jsonb),
      'sent_today',COALESCE((SELECT sent_count FROM daily_send_counters WHERE campaign_id=l.campaign_id AND send_date=(now() AT TIME ZONE 'UTC')::date),0),
      'dup_elsewhere',EXISTS(SELECT 1 FROM leads x WHERE x.email_norm=l.email_norm AND x.lead_id<>l.lead_id AND x.current_status IN('SENT','REPLIED','BOUNCED','UNSUBSCRIBED')),
      'is_suppressed',EXISTS(SELECT 1 FROM suppression s WHERE s.email_norm=l.email_norm),
      'idempotency_conflict',(SELECT COUNT(*) FROM send_queue q2 WHERE q2.idempotency_key=q.idempotency_key AND q2.queue_id<>q.queue_id),
      'pending_ambiguous_review',EXISTS(SELECT 1 FROM review_queue r WHERE r.lead_id=l.lead_id AND r.review_type='AMBIGUOUS_SEND' AND r.status='PENDING'),
      'provider_message_id',q.provider_message_id,
      'health',COALESCE((SELECT jsonb_agg(to_jsonb(h)) FROM critical_health h),'[]'::jsonb),
      'flags',COALESCE((SELECT jsonb_object_agg(flag_key,flag_value) FROM system_flags WHERE flag_key IN('GLOBAL_SEND_PERMISSION','CIRCUIT_BREAKER','SYSTEM_ANOMALY')),'{}'::jsonb),
      'supported_claim_ids',COALESCE((SELECT jsonb_agg(ec.claim_id) FROM evidence_claims ec WHERE ec.lead_id=l.lead_id AND ec.verification_status='SUPPORTED'),'[]'::jsonb),
      'active_lock_count',(SELECT COUNT(*) FROM send_locks sl WHERE sl.lead_id=l.lead_id AND sl.expires_at>now()),
      'active_lock_holder',(SELECT sl.holder FROM send_locks sl WHERE sl.lead_id=l.lead_id AND sl.expires_at>now() ORDER BY sl.expires_at DESC LIMIT 1),
      'lock_seconds_remaining',GREATEST(0,EXTRACT(EPOCH FROM((SELECT sl.expires_at FROM send_locks sl WHERE sl.lead_id=l.lead_id AND sl.holder=$2 AND sl.expires_at>now() LIMIT 1)-now()))),
      'autonomous_run_missing',CASE WHEN q.autonomous_run_id IS NULL THEN false ELSE NOT EXISTS(SELECT 1 FROM autonomous_campaign_runs ar WHERE ar.discovery_run_id=q.autonomous_run_id) END,
      'autonomous_slot_count',CASE WHEN q.autonomous_run_id IS NULL THEN 0 ELSE (SELECT COUNT(*) FROM send_queue qs WHERE qs.autonomous_run_id=q.autonomous_run_id AND qs.state IN('QUEUED','SENDING','RETRY_WAIT','AMBIGUOUS','SENT')) END,
      'autonomous_requested_send_count',CASE WHEN q.autonomous_run_id IS NULL THEN 0 ELSE COALESCE((SELECT requested_send_count FROM autonomous_campaign_runs ar WHERE ar.discovery_run_id=q.autonomous_run_id),0) END,
      'email_provider_url',$4,
      'next_route','SEND','response_required',false
    ) AS result
    FROM leads l
    JOIN campaigns c ON c.campaign_id=l.campaign_id
    JOIN send_queue q ON q.queue_id=$3 AND q.lead_id=l.lead_id AND q.state='SENDING'
    LEFT JOIN LATERAL(SELECT * FROM email_drafts WHERE lead_id=l.lead_id ORDER BY created_at DESC LIMIT 1)d ON true
    WHERE l.lead_id=$1 AND q.provider_message_id IS NULL
    UNION ALL
    SELECT jsonb_build_object(
      'db_ok',true,'db_action','final_provider_recheck_missing',
      'lead',to_jsonb(l),'campaign',to_jsonb(c),
      'queue',NULL,
      'holder',$2,'queue_id',$3,
      'email_provider_url',$4,
      'next_route','SEND','response_required',false
    ) AS result
    FROM leads l
    JOIN campaigns c ON c.campaign_id=l.campaign_id
    WHERE l.lead_id=$1
      AND NOT EXISTS(
        SELECT 1 FROM send_queue qx
        WHERE qx.queue_id=$3 AND qx.lead_id=$1 AND qx.state='SENDING' AND qx.provider_message_id IS NULL
      );`;
  return out('DB',{sql,params:[$json.lead_id,$json.holder,$json.queue_id,providerUrl],phase:'FINAL_PROVIDER_RECHECK',
    provider_action:'await_provider_gate',email_send_context:ctxSend,db_action:'final_provider_recheck_request'});
}
if($json.db_action==='sending_prepared' && $json.sending_cas_applied!==true){
  return final({sent:false,reason:$json.response_body?.reason||'SENDING_CAS_FAILED',lead_id:$json.lead_id},409);
}
if($json.db_action==='final_provider_recheck_missing'){
  const ctx=$json.email_send_context||{};
  const qid=ctx.queue_id||$json.queue_id||null;
  const lid=ctx.lead_id||$json.lead_id;
  const cid=ctx.campaign_id||null;
  const holder=ctx.holder||$json.holder;
  return out('DB',{
    sql:`WITH q AS(
      UPDATE send_queue
      SET state='QUEUED',next_attempt_at=NULL
      WHERE queue_id=$1 AND lead_id=$2 AND campaign_id=$3 AND state='SENDING' AND provider_message_id IS NULL
        AND EXISTS(SELECT 1 FROM send_locks sl WHERE sl.lead_id=$2 AND sl.holder=$5 AND sl.expires_at>now())
        AND (SELECT COUNT(*) FROM send_locks sl2 WHERE sl2.lead_id=$2 AND sl2.expires_at>now())=1
      RETURNING queue_id
    ),
    c AS(
      UPDATE daily_send_counters d
      SET sent_count=GREATEST(0,d.sent_count-1)
      WHERE d.campaign_id=$3 AND d.send_date=(now() AT TIME ZONE 'UTC')::date AND $4::boolean
        AND EXISTS(SELECT 1 FROM q)
      RETURNING campaign_id
    ),
    a AS(
      INSERT INTO audit_events(ts,event_type,lead_id,campaign_id,metadata)
      SELECT now(),'FINAL_PROVIDER_RECHECK_MISSING',$2,$3,jsonb_build_object('queue_id',$1,'reservation_released',$4)
      WHERE EXISTS(SELECT 1 FROM q) RETURNING 1
    ),
    l AS(DELETE FROM send_locks WHERE lead_id=$2 AND holder=$5 AND EXISTS(SELECT 1 FROM q) RETURNING lead_id)
    SELECT jsonb_build_object(
      'db_ok',true,'db_action','final_provider_recheck_blocked','next_route','FINAL',
      'response_required',true,'response_code',409,
      'response_body',jsonb_build_object('sent',false,'reason','FINAL_PROVIDER_RECHECK_MISSING','lead_id',$2),
      'queue_rollback_applied',EXISTS(SELECT 1 FROM q)
    ) AS result;`,
    params:[qid,lid,cid,ctx.reservation_acquired===true,holder]
  });
}
if($json.db_action==='final_provider_recheck'){
  const L=$json.lead||{},C=$json.campaign||{},D=$json.draft||{},Q=$json.queue||{};
  const health=Array.isArray($json.health)?$json.health:[],flags={...($json.flags||{})};
  const qctx=$json.email_send_context||{};
  const providerUrl=String($env.EMAIL_PROVIDER_SEND_URL||'');
  const errs=gate({
    ...L,...C,
    draft_created_at:D.created_at,draft_subject:D.subject,draft_body:D.body,draft_to_email:D.to_email,
    latest_draft_id:D.draft_id,queue_state:Q.state,queue_id:Q.queue_id,expected_queue_id:qctx.queue_id,
    queue_campaign_id:Q.campaign_id,queue_draft_id:Q.draft_id,attempt_count:Q.attempt_count,next_attempt_at:Q.next_attempt_at,idempotency_key:Q.idempotency_key,provider_message_id:Q.provider_message_id,
    sent_today:$json.sent_today,dup_elsewhere:$json.dup_elsewhere,is_suppressed:$json.is_suppressed,
    latest_qa_draft_id:$json.latest_qa_draft_id,latest_qa_decision:$json.latest_qa_decision,
    draft_claim_ids:D.claim_ids||[],qa_result:L.qa_result,
    qa_claim_verification_overall:$json.qa_claim_verification_overall,
    qa_supported_claim_ids:Array.isArray($json.qa_supported_claim_ids)?$json.qa_supported_claim_ids:[],
    idempotency_conflict:$json.idempotency_conflict,pending_ambiguous_review:$json.pending_ambiguous_review,
    reservation_acquired:qctx.reservation_acquired,reserved_sent_count:Number(qctx.reserved_sent_count||0),
    daily_after_reservation:Number($json.sent_today||0),
    lock_count:Number($json.active_lock_count||0),lock_holder:$json.active_lock_holder,holder:qctx.holder,
    lock_seconds_remaining:Number($json.lock_seconds_remaining||0),
    autonomous_run_id:Q.autonomous_run_id,autonomous_run_missing:$json.autonomous_run_missing,
    autonomous_slot_count:Number($json.autonomous_slot_count||0),
    autonomous_requested_send_count:Number($json.autonomous_requested_send_count||0),
    email_provider_url:$json.email_provider_url
  },health,flags,new Date().toISOString(),'PROVIDER_SEND');

  if(errs.length){
    const rollbackSql=`WITH q AS(
        UPDATE send_queue SET state='QUEUED',next_attempt_at=NULL
        WHERE queue_id=$1 AND lead_id=$2 AND campaign_id=$3 AND state='SENDING' AND provider_message_id IS NULL
          AND EXISTS(SELECT 1 FROM send_locks sl WHERE sl.lead_id=$2 AND sl.holder=$6 AND sl.expires_at>now())
          AND (SELECT COUNT(*) FROM send_locks sl2 WHERE sl2.lead_id=$2 AND sl2.expires_at>now())=1
        RETURNING queue_id
      ),
      c AS(
        UPDATE daily_send_counters d
        SET sent_count=GREATEST(0,d.sent_count-1)
        WHERE d.campaign_id=$3 AND d.send_date=(now() AT TIME ZONE 'UTC')::date AND $4::boolean
          AND EXISTS(SELECT 1 FROM q)
      ),
      a AS(
        INSERT INTO audit_events(ts,event_type,lead_id,campaign_id,metadata)
        SELECT now(),'FINAL_PROVIDER_GATE_BLOCKED',$2,$3,
          jsonb_build_object('queue_id',$1,'reasons',$5::jsonb,'reservation_released',$4)
      ),
      l AS(DELETE FROM send_locks WHERE lead_id=$2 AND holder=$6 AND EXISTS(SELECT 1 FROM q) RETURNING lead_id)
      SELECT jsonb_build_object(
        'db_ok',true,'db_action','final_provider_gate_blocked','next_route','FINAL',
        'response_required',true,'response_code',409,
        'response_body',jsonb_build_object('sent',false,'reason',$7,'all_reasons',$5::jsonb,'lead_id',$2),
        'queue_rollback_applied',EXISTS(SELECT 1 FROM q)
      ) AS result;`;
    return out('DB',{sql:rollbackSql,params:[
      qctx.queue_id,qctx.lead_id,qctx.campaign_id,
      qctx.reservation_acquired===true,
      JSON.stringify(errs),qctx.holder,errs[0]
    ]});
  }

  const authorized={...qctx,
    provider_gate_passed:true,
    provider_gate_checked_at:new Date().toISOString(),
    queue_state:'SENDING',
    provider_message_id:null,
    draft_to_email:D.to_email,
