          updated_by=excluded.updated_by,reason=excluded.reason
    RETURNING flag_key
  ),
  set_permission AS(
    INSERT INTO system_flags(flag_key,flag_value,updated_at,updated_by,reason)
    SELECT 'GLOBAL_SEND_PERMISSION','TRUE',now(),'circuit_breaker',
      'automatic recovery verified healthy streak'
    FROM recovery r
    WHERE r.action='CLOSE_AND_RESTORE'
    ON CONFLICT(flag_key) DO UPDATE
      SET flag_value='TRUE',updated_at=excluded.updated_at,
          updated_by=excluded.updated_by,reason=excluded.reason
    RETURNING flag_key
  ),
  set_streak AS(
    INSERT INTO system_flags(flag_key,flag_value,updated_at,updated_by,reason)
    SELECT 'RECOVERY_HEALTH_STREAK',
      CASE WHEN r.action='ENTER_RECOVERY_TEST' THEN '1'
           WHEN r.action='HEALTHY_STREAK_PROGRESS' THEN '1'
           WHEN r.action='CLOSE_AND_RESTORE' THEN '0'
           WHEN r.action='RESET_RECOVERY_STREAK' THEN '0'
           ELSE f.streak END,
      now(),'circuit_breaker',r.action
    FROM recovery r CROSS JOIN current_flags f
    WHERE r.action<>'NOOP'
    ON CONFLICT(flag_key) DO UPDATE
      SET flag_value=excluded.flag_value,updated_at=excluded.updated_at,
          updated_by=excluded.updated_by,reason=excluded.reason
    RETURNING flag_key
  ),
  recovery_audit AS(
    INSERT INTO audit_events(ts,event_type,source_system,metadata)
    SELECT now(),'Circuit Breaker Automatic Recovery','recovery',
      jsonb_build_object('action',r.action,'healthy_critical_deps',r.healthy_count)
    FROM recovery r WHERE r.action<>'NOOP'
    RETURNING 1
  ),
  stuck AS(
    SELECT q.queue_id,q.lead_id,q.campaign_id,q.idempotency_key,q.provider_message_id,q.attempt_count,q.autonomous_run_id
    FROM send_queue q WHERE q.state='SENDING' AND q.last_attempt_at IS NOT NULL AND q.last_attempt_at<now()-interval '10 minutes' AND q.provider_message_id IS NULL
      AND NOT EXISTS(SELECT 1 FROM send_locks sl WHERE sl.lead_id=q.lead_id AND sl.expires_at>now())
  ),
  retry_ready AS(
    SELECT q.queue_id,q.lead_id,q.campaign_id,q.idempotency_key,q.provider_message_id,q.attempt_count,q.autonomous_run_id
    FROM send_queue q WHERE q.state='RETRY_WAIT' AND q.next_attempt_at IS NOT NULL AND q.next_attempt_at<=now() AND q.provider_message_id IS NULL AND q.attempt_count IS NOT NULL AND q.attempt_count>=0 AND q.attempt_count<3
  ),
  marked AS(
    UPDATE send_queue q SET state='AMBIGUOUS'
    FROM stuck s
    WHERE q.queue_id=s.queue_id AND q.lead_id=s.lead_id
      AND q.state='SENDING' AND q.provider_message_id IS NULL
    RETURNING q.queue_id,q.lead_id,q.campaign_id,q.idempotency_key,q.provider_message_id,q.attempt_count
  ),
  reviews AS(
    INSERT INTO review_queue(review_id,lead_id,review_type,reason,status,created_at)
    SELECT gen_random_uuid(),lead_id,'AMBIGUOUS_SEND',
      'stuck in SENDING with no provider_message_id after restart; exact row requires reconciliation; NO AUTOMATIC RESEND',
      'PENDING',now()
    FROM marked ON CONFLICT DO NOTHING RETURNING review_id
  ),
  crash_audit AS(
    INSERT INTO audit_events(ts,event_type,source_system,metadata)
    SELECT now(),'Crash Recovery Marked AMBIGUOUS','recovery',
      jsonb_build_object('count',(SELECT COUNT(*) FROM marked))
    WHERE EXISTS(SELECT 1 FROM marked)
    RETURNING 1
  )
  SELECT jsonb_build_object(
    'db_ok',true,'db_action','scheduled_runtime_maintenance','next_route','AUTO','response_required',false,
    'recovery_action',(SELECT action FROM recovery),
    'healthy_critical_deps',(SELECT healthy_count FROM recovery),
    'rows',COALESCE((SELECT jsonb_agg(to_jsonb(marked)) FROM marked),'[]'::jsonb),
    'retry_rows',COALESCE((SELECT jsonb_agg(to_jsonb(retry_ready)) FROM retry_ready),'[]'::jsonb)
  ) AS result;`;
  return out('DB',{sql:recoverySql,params:[]});
}
if($json.db_action==='scheduled_runtime_maintenance'){
  const rows=Array.isArray($json.rows)?$json.rows:[],retries=Array.isArray($json.retry_rows)?$json.retry_rows:[],outRows=[];
