if(src==='Autonomous: Discovery Recovery Sweep (Every 10 Minutes)'){
  return out('DB',{sql:`WITH c AS(
    SELECT discovery_run_id
    FROM autonomous_campaign_runs
    WHERE (
      (
        final_target_status IN('DISCOVERY_IN_PROGRESS','PROCESSING_IN_PROGRESS','REPLACEMENT_DISCOVERY_IN_PROGRESS')
