    ORDER BY updated_at
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  ),u AS(
    UPDATE autonomous_campaign_runs r
    SET recovery_claim_id=gen_random_uuid()::text,recovery_claimed_at=now(),updated_at=now()
    FROM c WHERE r.discovery_run_id=c.discovery_run_id
