if($json.db_action==='discovery_recovery_claim'){
  if(!$json.run)return [];
  if(!String($env.DISCOVERY_PROVIDER_API_URL||'').trim())return out('DB',{sql:`UPDATE autonomous_campaign_runs SET final_target_status='EXTERNAL_DEPENDENCY_REQUIRED',stop_reason='DISCOVERY_PROVIDER_API_URL_NOT_CONFIGURED',recovery_claim_id=NULL,recovery_claimed_at=NULL,updated_at=now() WHERE discovery_run_id=$1;`,
