if($json.auto_stage==='NEXT_CANDIDATE'){
  const run=JSON.parse(JSON.stringify($json.discovery_run||{}));
  const cfg=run.config||{};
  const requiredRunId=run.discovery_run_id;
  if(!requiredRunId)return fail('DISCOVERY_RUN_ID_MISSING',409);
  const counterSql=`WITH
  run AS(
    SELECT discovery_run_id,qualified_company_count,rejected_company_count,duplicate_company_count,
           research_ready_count,verified_contact_count,downstream_failed_count,
           discovery_attempt_count,discovery_batch_count,discovery_page_count,discovered_candidate_count
    FROM autonomous_campaign_runs
    WHERE discovery_run_id=$1
  ),
  e AS(
    SELECT event_type,metadata,ts
    FROM audit_events
    WHERE source_system='autonomous' AND metadata->>'discovery_run_id'=$1
  ),
  c AS(
    SELECT COUNT(*) FILTER(WHERE event_type='Autonomous Candidate Qualified') AS qualified_event,
           COUNT(*) FILTER(WHERE event_type IN('Autonomous Candidate Rejected','Autonomous Candidate Intake Rejected')) AS rejected_event,
           COUNT(*) FILTER(WHERE event_type IN('Autonomous Candidate Duplicate','Autonomous Pre-Intake Duplicate')) AS duplicate_event,
           COUNT(*) FILTER(WHERE event_type='Autonomous Discovery Batch Returned') AS attempts_event,
           COALESCE(SUM(CASE WHEN event_type='Autonomous Discovery Batch Returned'
                             THEN COALESCE(NULLIF(metadata->>'candidate_count','')::int,0) ELSE 0 END),0) AS candidates_seen_event,
           COALESCE(MAX(CASE WHEN event_type='Autonomous Discovery Batch Returned'
                             THEN NULLIF(metadata->>'provider_page','')::int ELSE NULL END),0) AS max_page_event,
           COUNT(*) FILTER(WHERE metadata->>'dependency_state'='EXTERNAL_DEPENDENCY_REQUIRED') AS dependency_holds
    FROM e
  ),
  lead_map AS(
    SELECT l.current_status,l.research_status,l.verification_status,l.external_dependency_state
    FROM leads l
    WHERE l.target_parameters IS NOT NULL
      AND (l.target_parameters::jsonb->>'discovery_run_id')=$1
  ),
  lc AS(
    SELECT COUNT(*) FILTER(WHERE external_dependency_state='EXTERNAL_DEPENDENCY_REQUIRED'
                            OR research_status='EXTERNAL_DEPENDENCY_REQUIRED') AS lead_dependency_holds
    FROM lead_map
  ),
  qc AS(
    SELECT COUNT(*) FILTER(WHERE state='QUEUED') AS queued_count,
           COUNT(*) FILTER(WHERE state='SENDING') AS sending_count,
           COUNT(*) FILTER(WHERE state='RETRY_WAIT') AS retry_wait_count,
           COUNT(*) FILTER(WHERE state='AMBIGUOUS') AS ambiguous_count,
           COUNT(*) FILTER(WHERE state IN('SENDING','AMBIGUOUS')) AS active_reservation_count,
           COUNT(*) FILTER(WHERE state='SENT') AS sent_company_count,
           COUNT(*) FILTER(WHERE state IN('FAILED','CANCELLED')) AS failed_company_count,
           COUNT(*) FILTER(WHERE state IN('QUEUED','SENDING','RETRY_WAIT','AMBIGUOUS','SENT')) AS send_slots
    FROM send_queue WHERE autonomous_run_id=$1
  ),
  flags AS(
    SELECT MAX(flag_value) FILTER(WHERE flag_key='GLOBAL_SEND_PERMISSION') AS global_send_permission,
           MAX(flag_value) FILTER(WHERE flag_key='CIRCUIT_BREAKER') AS circuit_breaker
    FROM system_flags
    WHERE flag_key IN('GLOBAL_SEND_PERMISSION','CIRCUIT_BREAKER')
  ),
  health AS(
    SELECT COUNT(*) FILTER(
             WHERE status='HEALTHY' AND checked_at>now()-interval '15 minutes' AND checked_at<=now()
           ) AS healthy_critical_deps
    FROM(
      SELECT DISTINCT ON(component)component,status,checked_at
      FROM health_checks
      WHERE component IN('database','queue','email_provider','workflow_engine')
      ORDER BY component,checked_at DESC NULLS LAST
    )h
  )
  SELECT
    COALESCE(run.qualified_company_count,c.qualified_event) AS qualified,
    COALESCE(run.rejected_company_count,c.rejected_event) AS rejected,
    COALESCE(run.duplicate_company_count,c.duplicate_event) AS duplicate,
    COALESCE(run.discovery_attempt_count,c.attempts_event) AS attempts,
    COALESCE(run.discovered_candidate_count,c.candidates_seen_event) AS candidates_seen,
    COALESCE(run.discovery_page_count,c.max_page_event) AS max_page,
    c.dependency_holds,
    COALESCE(run.research_ready_count,0) AS research_ready,
    COALESCE(run.verified_contact_count,0) AS verified_contact,
    qc.send_slots,qc.queued_count,qc.sending_count,qc.retry_wait_count,qc.ambiguous_count,
    qc.active_reservation_count,qc.sent_company_count,qc.failed_company_count,
    COALESCE(run.downstream_failed_count,0) AS downstream_failed,
    (c.dependency_holds+lc.lead_dependency_holds) AS external_dependency_count,
    flags.global_send_permission,flags.circuit_breaker,health.healthy_critical_deps,
    jsonb_build_object(
      'db_ok',true,'db_action','autonomous_counters','next_route','AUTO','response_required',false
    ) AS result
  FROM run
  CROSS JOIN c CROSS JOIN lc CROSS JOIN qc CROSS JOIN flags CROSS JOIN health;`;
  return out('DB',{
    sql:counterSql,
    params:[requiredRunId],
    auto_stage:'AUTONOMOUS_COUNTERS',
    discovery_run:run,
    candidates:$json.candidates||[],
    target_parameters:$json.target_parameters||run.target_parameters||{},
    candidate_index:Number($json.candidate_index||0)
  });
}
if($json.db_action==='autonomous_counters'){
  const x=$json;
  const r=JSON.parse(JSON.stringify(x.discovery_run||{}));
  const ctr=x;
  const arr=x.candidates||[];
  const idx=Number(x.candidate_index||0);
  const cfg=r.config||{};
  const nums=['qualified','rejected','duplicate','attempts','candidates_seen','max_page','dependency_holds',
    'research_ready','verified_contact','send_slots','queued_count','sending_count','retry_wait_count',
    'ambiguous_count','active_reservation_count','sent_company_count','failed_company_count',
    'downstream_failed','external_dependency_count','healthy_critical_deps'];
  const valid=n=>Object.prototype.hasOwnProperty.call(ctr,n)&&ctr[n]!==null&&ctr[n]!==''&&Number.isFinite(Number(ctr[n]))&&Number.isInteger(Number(ctr[n]))&&Number(ctr[n])>=0;
  if(!nums.every(valid)||typeof ctr.global_send_permission!=='string'||typeof ctr.circuit_breaker!=='string'){
    const safe={...r,counter_read_status:'UNKNOWN',discovery_status:'SAFETY_HOLD',final_target_status:'SAFETY_HOLD',execution_state:'SAFETY_HOLD',discovery_stop_reason:'DISCOVERY_COUNTER_READ_UNKNOWN',discovery_exhausted:true};
    return out('DB',{
      sql:`UPDATE autonomous_campaign_runs SET final_target_status='SAFETY_HOLD',stop_reason='DISCOVERY_COUNTER_READ_UNKNOWN',
             state_json=$2::jsonb,completed_at=now(),updated_at=now()
           WHERE discovery_run_id=$1
           RETURNING jsonb_build_object('db_ok',true,'db_action','autonomous_terminal','next_route','FINAL',
             'response_required',false,'status','SAFETY_HOLD') AS result;`,
      params:[r.discovery_run_id,JSON.stringify(safe)],
      next_route:'FINAL',response_required:false,
      discovery_run:safe
    });
  }

  const num=k=>Number(ctr[k]);
  const requestedCompany=Math.max(1,Number(r.requested_company_count||r.quantity_requested||0));
  const requestedSend=Math.max(0,Number(r.requested_send_count||0));
  const discoveryOnly=r.discovery_only===true;
  const qualified=num('qualified'),rejected=num('rejected'),duplicate=num('duplicate');
  const attempts=Math.max(num('attempts'),Number(r.discovery_attempt_count||0));
  const batches=Math.max(Number(r.discovery_batch_count||0),attempts);
  const pages=Math.max(num('max_page'),Number(r.discovery_page_count||0));
  const candidatesSeen=num('candidates_seen');
  const researchReady=num('research_ready'),verified=num('verified_contact'),sendSlots=num('send_slots');
  const queued=num('queued_count'),sending=num('sending_count'),retryWait=num('retry_wait_count'),ambiguous=num('ambiguous_count');
  const activeReservation=num('active_reservation_count'),sent=num('sent_company_count'),failed=num('failed_company_count'),downstreamFailed=num('downstream_failed');
  const progress=discoveryOnly?qualified:sendSlots;
  const target=discoveryOnly?requestedCompany:requestedSend;
  const remaining=Math.max(target-progress,0);
  const elapsed=Date.now()-new Date(r.discovery_started_at||Date.now()).getTime();

  let status='DISCOVERY_IN_PROGRESS',stopReason=null;
  if(discoveryOnly&&qualified>=requestedCompany)status='TARGET_QUALIFIED_REACHED';
  else if(!discoveryOnly&&requestedSend>0&&sent>=requestedSend)status='TARGET_SEND_COMPLETED';
  else if(!discoveryOnly&&requestedSend>0&&sendSlots>=requestedSend)status='TARGET_SENDABLE_COUNT_REACHED';
  else if(!discoveryOnly&&String(ctr.global_send_permission).toUpperCase()!=='TRUE'){status='GLOBAL_SEND_PAUSED';stopReason='GLOBAL_SEND_PERMISSION_FALSE_OR_UNKNOWN';}
  else if(!discoveryOnly&&num('healthy_critical_deps')!==4){status='GLOBAL_SEND_PAUSED';stopReason='CRITICAL_DEPENDENCY_UNHEALTHY_OR_STALE';}
  else if(!discoveryOnly&&String(ctr.circuit_breaker).toUpperCase()!=='CLOSED'){status='GLOBAL_SEND_PAUSED';stopReason='CIRCUIT_BREAKER_OPEN_OR_UNKNOWN';}
  else if(elapsed>Number(cfg.max_runtime_minutes||120)*60000){status='DISCOVERY_RUNTIME_EXHAUSTED';stopReason='MAX_RUNTIME_EXCEEDED';}
  else if(!discoveryOnly&&num('external_dependency_count')>0){status='EXTERNAL_DEPENDENCY_REQUIRED';stopReason='EXTERNAL_DEPENDENCY_REQUIRED';}
  else if(Number(r.iteration||0)>=Number(cfg.max_iterations_global||500)){status='DISCOVERY_BUDGET_EXHAUSTED';stopReason='MAX_DISCOVERY_ITERATIONS';}
  else if(batches>=Number(cfg.max_provider_batches_global||1000)){status='DISCOVERY_BUDGET_EXHAUSTED';stopReason='MAX_PROVIDER_BATCHES';}
  else if(pages>=Number(cfg.max_provider_pages_global||1000)&&r.next_has_more){status='DISCOVERY_BUDGET_EXHAUSTED';stopReason='MAX_PROVIDER_PAGES';}
  else if(candidatesSeen>=Number(cfg.effective_max_total_candidates||cfg.max_total_candidates_global||10000)){status='DISCOVERY_BUDGET_EXHAUSTED';stopReason='MAX_TOTAL_CANDIDATES';}
  else if(Number(r.next_query_index||0)>=Number((r.queries||[]).length)&&!r.next_has_more){status='SAFE_SHORTFALL';stopReason='DISCOVERY_STRATEGIES_EXHAUSTED';}
  else status=!discoveryOnly&&downstreamFailed>0?'REPLACEMENT_DISCOVERY_IN_PROGRESS':'DISCOVERY_IN_PROGRESS';

  const discoveryShortfall=Math.max(requestedCompany-qualified,0);
  const sendShortfall=Math.max(requestedSend-sent,0);
  const replacementShortfall=discoveryOnly?0:Math.max(requestedSend-sendSlots,0);
  const nextRun={...r,
    requested_company_count:requestedCompany,requested_send_count:requestedSend,
    qualified_company_count:qualified,research_ready_count:researchReady,verified_contact_count:verified,
    sendable_company_count:sendSlots,queued_count:queued,sending_count:sending,retry_wait_count:retryWait,
    ambiguous_count:ambiguous,active_reservation_count:activeReservation,sent_company_count:sent,
    failed_company_count:failed,downstream_failed_count:downstreamFailed,
    replacement_shortfall:replacementShortfall,remaining_send_shortfall:sendShortfall,discovery_shortfall:discoveryShortfall,
    rejected_company_count:rejected,duplicate_company_count:duplicate,discovery_attempt_count:attempts,
    discovery_batch_count:batches,discovery_page_count:pages,final_provider_candidates_seen:candidatesSeen,
    final_target_status:status,discovery_status:status,discovery_stop_reason:stopReason,
    execution_state:status,target_send_completion_eligible:(!discoveryOnly&&requestedSend>0&&sent>=requestedSend),
    counter_read_status:'VALID'
  };
  if(['SAFE_SHORTFALL','DISCOVERY_BUDGET_EXHAUSTED','DISCOVERY_RUNTIME_EXHAUSTED','PROVIDER_UNAVAILABLE','EXTERNAL_DEPENDENCY_REQUIRED','GLOBAL_SEND_PAUSED','SAFETY_HOLD','TARGET_SEND_COMPLETED','TARGET_QUALIFIED_REACHED','TARGET_SENDABLE_COUNT_REACHED'].includes(status)){
    nextRun.discovery_exhausted=['TARGET_SEND_COMPLETED','TARGET_QUALIFIED_REACHED'].includes(status)?false:remaining>0;
    const terminal = ['TARGET_SENDABLE_COUNT_REACHED'].includes(status) ? false : true;
    const completed = ['TARGET_SEND_COMPLETED','TARGET_QUALIFIED_REACHED','SAFE_SHORTFALL','DISCOVERY_BUDGET_EXHAUSTED','DISCOVERY_RUNTIME_EXHAUSTED','PROVIDER_UNAVAILABLE','GLOBAL_SEND_PAUSED','EXTERNAL_DEPENDENCY_REQUIRED','SAFETY_HOLD'].includes(status);
    const statusSql=`UPDATE autonomous_campaign_runs
      SET qualified_company_count=$2,research_ready_count=$3,verified_contact_count=$4,
          sendable_company_count=$5,queued_count=$6,sent_company_count=$7,downstream_failed_count=$8,
          replacement_shortfall=$9,remaining_send_shortfall=$10,discovery_shortfall=$11,
          discovered_candidate_count=$12,final_target_status=$13,stop_reason=$14,
          state_json=$15::jsonb,
          completed_at=CASE WHEN $13 IN('TARGET_SEND_COMPLETED','TARGET_QUALIFIED_REACHED','SAFE_SHORTFALL','DISCOVERY_BUDGET_EXHAUSTED','DISCOVERY_RUNTIME_EXHAUSTED','PROVIDER_UNAVAILABLE','GLOBAL_SEND_PAUSED','EXTERNAL_DEPENDENCY_REQUIRED','SAFETY_HOLD') THEN now()
             WHEN $13='TARGET_SENDABLE_COUNT_REACHED' THEN NULL ELSE completed_at END,
          updated_at=now()
      WHERE discovery_run_id=$1;
      INSERT INTO audit_events(ts,event_type,campaign_id,source_system,metadata)
      VALUES(now(),CASE WHEN $13='TARGET_SENDABLE_COUNT_REACHED' THEN 'Autonomous Discovery Intermediate State' ELSE 'Autonomous Discovery Terminal State' END,
        $16,'autonomous',$17::jsonb);
      SELECT jsonb_build_object('db_ok',true,'db_action','autonomous_status_recorded','next_route',$18,
        'response_required',false,'status',$13) AS result;`;
    return out('DB',{
      sql:statusSql,
      params:[nextRun.discovery_run_id,nextRun.qualified_company_count,nextRun.research_ready_count,nextRun.verified_contact_count,
        nextRun.sendable_company_count,nextRun.queued_count,nextRun.sent_company_count,nextRun.downstream_failed_count,
        nextRun.replacement_shortfall,nextRun.remaining_send_shortfall,nextRun.discovery_shortfall,nextRun.final_provider_candidates_seen,
        nextRun.final_target_status,nextRun.discovery_stop_reason,JSON.stringify(nextRun),nextRun.campaign_id||null,
        JSON.stringify({discovery_run_id:nextRun.discovery_run_id,final_target_status:nextRun.final_target_status,stop_reason:nextRun.discovery_stop_reason}),
